import{_ as e,c as p,o as r,ah as s}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"22、【賁】 離下艮上","description":"周易尚氏學 - 22、【賁】 離下艮上","frontmatter":{"title":"22、【賁】 離下艮上","description":"周易尚氏學 - 22、【賁】 離下艮上"},"headers":[],"relativePath":"classics/shangshi/027.md","filePath":"classics/shangshi/027.md"}'),i={name:"classics/shangshi/027.md"};function t(h,a,n,l,c,o){return r(),p("div",null,[...a[0]||(a[0]=[s('<h1 id="_22、【賁】-離下艮上" tabindex="-1">22、【賁】 離下艮上 <a class="header-anchor" href="#_22、【賁】-離下艮上" aria-label="Permalink to “22、【賁】 離下艮上”">​</a></h1><p>歸藏作熒惑。熒惑火星。史記察剛氣以處熒惑。曰南方火。主夏日。丙丁是也。卦上艮為星。離亦為星。下離為火。艮亦為火。離主夏位南。艮納丙亦南。故曰熒惑。於象恰合。至周易作賁。賁。釋文雲。傅氏作斑。文章貌。鄭雲文飾貌。太玄擬作飾。按卦一陰一陽相雜。相雜則有文。故曰斑。曰文飾。又按爾雅。龜三足曰賁。卦離艮皆為龜。而震為足。數三。正龜三足也。初二曰其趾其須。九三雲儒如。六四雲皤如。言其形也。上九雲白賁。言其色也。雜卦雲。責無色也。艮為黔。坎為隱伏。為黑。亦無色。無色即不明。不明故象言無敢折獄。蓋山下有火。與地下有火略同。地下有火明夷。山下有火等耳。故孔子筮得賁不樂。以與明夷同也。後人謂山下有火。明不及遠。皆讀下為旁。故其義永不能通。前一義舊解皆從之。後一義鮮有述之者。故引信其義。以俟深於易理者定奪焉。</p><p>亨謂二。離夏故亨。傳所謂柔來文剛也。小謂五。分泰二居上。五得中承陽。故曰小利有攸往。言利往五也。唐郭京舉正。謂小為不。非。</p><p>彖曰。貴亨。柔來而文剛。故亨。分剛上而文柔。故小利有攸往。天文也。文明以上。人文也。觀乎天丈以察時變。觀乎人文以化成天下。</p><p>卦剛柔相雜故曰文。離日坎月。民星震辰。天文。離禮震樂。人文。離夏震春坎冬。故曰以察時變。震為生。艮為成。為天。故曰化成天下。朱子雲。先儒說。天文上當有剛柔交錯四字。</p><p>象曰。山下有火。賁。君子以明庶政。無敢折獄。</p><p>山下非山旁。火在山下。與地下同。直明夷耳。後儒謂明不及遠者誤也。艮為君子。明庶政。象每以相反見義。如同人曰類旅辨物。無妄曰時育萬物。蠱曰振民育德皆是。茲因賁不明。君子反以明庶政。坎為獄。折獄須明。離在下不明。故無敢折獄。而無敢折獄。尤賁為無色無明之確徵。</p><p>初九。賁其趾。舍車而徒。</p><p>初應在四。四震故曰趾。坎為車。初在車下。當然不乘而徒也。蓋初九正當勿用之時。安於徒步。以遂其志者也。</p><h3 id="象曰。舍車而徒。義弗來也。" tabindex="-1">象曰。舍車而徒。義弗來也。 <a class="header-anchor" href="#象曰。舍車而徒。義弗來也。" aria-label="Permalink to “象曰。舍車而徒。義弗來也。”">​</a></h3><p>徒謂徒步。義弗乘者。言志行高潔。不肯苟乘也。</p><p>六二。賁其須。</p><p>艮為須。象失傳。詳焦氏易詁艮須在上。下離文之。故曰賁其須。其指上卦。言六二之須。謂上艮也。泰二往上成艮。故曰興。二因得當位居中。故曰與上興。候果謂三至上有頤象。二在頤下。故有須象。雖巧切。不知艮即為須也。</p><h3 id="象曰。賁其須。與上興也。" tabindex="-1">象曰。賁其須。與上興也。 <a class="header-anchor" href="#象曰。賁其須。與上興也。" aria-label="Permalink to “象曰。賁其須。與上興也。”">​</a></h3><p>興起也。與上興。即喜上興也。</p><p>九三。貴如濡如。永佔吉。</p><p>坎水故曰德如。陽貞於三當位。前臨重陰。故曰永貞吉。</p><h3 id="象曰。永貞之吉。終莫之陵也。" tabindex="-1">象曰。永貞之吉。終莫之陵也。 <a class="header-anchor" href="#象曰。永貞之吉。終莫之陵也。" aria-label="Permalink to “象曰。永貞之吉。終莫之陵也。”">​</a></h3><p>之往也。三應在上。上艮為陵。乃上不應。故終莫之陵。永貞於三吉也。又前臨重陰。皆順三。無有陵越之患也。六四。賁如皤如。白馬翰如。匪寇婚媾。左傳宣二年。皤其腹。疏皤腹貌。卦三至上互大離。離為大腹。故曰皤如。釋文皤苟作波。鄭陸作幡（左蟲）。音煩。按皤通番。番音煩。鄭陸讀煩聲是也。凡易如此等辭。往往用韻。疑番與翰協。詩大雅申伯番番。徒御蟬蟬（左口）。戎有良翰。番與翰協。與此同也也。陸績雲。震為白。為馬。按震為羽翰。翰象失傳 詳焦氏易詁翰如馬行貌。言疾如羽翰也。四乘坎。坎為寇。疑其逼己。豈知四當位。下有正應。三無能害之。終得與初婚媾也。象曰。六四當位。疑也。匪寇婚媾。終無尤也。疑謂疑三。坎為疑。</p><p>六五。賁於丘園。束帛久久。吝。終吉。</p><p>艮為丘園。坤為帛。乾環約其兩端。故曰束帛。子夏傳。五匹為束。三玄二燻。象陰陽。戔戔。馬訓為委積。虞作多。易林旅之豐雲。束帛戔戔。膊（左貝）我孟宣。似亦以盛多為訓。俗解因戔通殘。便訓戔戔為薄物。又或作殘落者非也。儀禮士冠上虞禮。周禮大宗伯注。皆以束帛為十端。每端丈八尺。兩端合卷。決為五匹。皆與子夏傳同。然則束帛五匹者。乃先王之定製。戈戈乃形容束帛之盛。謂薄物固非。殘落尤謬也。下元應故吝。上承陽。故終吉。彖謂小利往。以此。</p><h3 id="象曰。六五之吉。有喜也。" tabindex="-1">象曰。六五之吉。有喜也。 <a class="header-anchor" href="#象曰。六五之吉。有喜也。" aria-label="Permalink to “象曰。六五之吉。有喜也。”">​</a></h3><p>五承陽。故有喜。</p><p>上九。白賁。無咎。</p><p>賁而曰白。其為物也明矣。若訓為飾為文為斑為黃白色。範望太玄視首上九注為色不純。高誘呂覽賁字注此二字皆不能通。諸儒據繪事後素。曲為之說。無當也。蓋艮為賁。責無色。故曰白賁。</p><h3 id="象曰。白賁無咎。上得志也。" tabindex="-1">象曰。白賁無咎。上得志也。 <a class="header-anchor" href="#象曰。白賁無咎。上得志也。" aria-label="Permalink to “象曰。白賁無咎。上得志也。”">​</a></h3><p>下乘重陰。故曰得志。言陽得陰而通也。大畜上九曰道大行也。損上九曰大得志。益九五曰大得志。頤上九曰大有慶。與此義皆同。乃二千年舊解。少能知其故者。真可謂也。</p>',27)])])}const m=e(i,[["render",t]]);export{_ as __pageData,m as default};
